package com.renamer

import android.app.Activity
import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.Gravity
import android.widget.*

/**
 * One section's full guide, as its own glass page
 * (not a small dialog), so long explanations are
 * fully readable and scrollable.
 *
 * RULES the user set for this page:
 * - The Subscriptions section is gone (1.29) and is not listed
 *   at all, and NO text anywhere hints that another (private)
 *   section exists. The entry-password text never mentions
 *   a private password.
 * - The Emergency section explains its full VISIBLE
 *   behaviour (fresh fetch, ping test, best server,
 *   nothing saved, generic name, retry, ping line).
 *   It NEVER reveals the hidden settings gesture,
 *   its password, or any subscription link: those
 *   stay hidden by design, even in this guide.
 * - Everything else is explained completely,
 *   especially features this app ADDED that the
 *   original apps do not have (flag circle, FAB
 *   long-press modes, smart connect, widgets,
 *   notification, drag reorder, login themes).
 *
 * STANDING RULE (2.81, user order): in EVERY future update, if
 * something changes and its guide text needs it, update the guide
 * too — both inside the section itself (HelpUi) and here in
 * Settings' Guide — proactively, without asking the user.
 */
class GuideDetailActivity : Activity() {
    private fun L(fa: String, en: String): String = AppLanguage.t(this, fa, en)
    private fun dp(v: Int): Int = (v * resources.displayMetrics.density).toInt()

    data class Block(val headFa: String, val headEn: String, val bodyFa: String, val bodyEn: String)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // 2.84: shared background + no white window strips.
        try { Theme.applyPage(this) } catch (_: Exception) {}
        val key = intent.getStringExtra("section") ?: "v2ray"
        val (titleFa, titleEn, blocks) = content(key)
        val dark = Theme.isDark(this)
        // 2.89: the background lives on the scroll (full-screen),
        // not on the content-height root — one uniform background.
        val scroll = ScrollView(this).apply {
            background = Theme.pageBackground(this@GuideDetailActivity)
            isFillViewport = true
            fitsSystemWindows = true
        }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
        }
        scroll.addView(root)
        val panel = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val d = GradientDrawable()
            d.shape = GradientDrawable.RECTANGLE
            d.cornerRadius = dp(24).toFloat()
            d.setColor(if (dark) Theme.darken(Color.parseColor("#CC1E1E1E")) else Color.parseColor("#E8FFFFFF"))
            d.setStroke(dp(1), if (dark) Theme.darken(Color.parseColor("#55FFFFFF")) else Color.parseColor("#88CCCCCC"))
            background = d
            setPadding(dp(20), dp(20), dp(20), dp(20))
        }
        panel.addView(TextView(this).apply {
            text = L(titleFa, titleEn); textSize = 19f
            setTypeface(android.graphics.Typeface.DEFAULT_BOLD)
            setTextColor(if (dark) Color.WHITE else Color.BLACK)
            textDirection = android.view.View.TEXT_DIRECTION_LOCALE
            gravity = Gravity.START
            setPadding(0, 0, 0, dp(12))
        })
        for (b in blocks) {
            panel.addView(TextView(this).apply {
                text = L(b.headFa, b.headEn); textSize = 15f
                setTypeface(android.graphics.Typeface.DEFAULT_BOLD)
                setTextColor(if (dark) Color.parseColor("#81C784") else Color.parseColor("#0B6E4F"))
                textDirection = android.view.View.TEXT_DIRECTION_LOCALE
                gravity = Gravity.START
                setPadding(0, dp(10), 0, dp(2))
            })
            panel.addView(TextView(this).apply {
                text = L(b.bodyFa, b.bodyEn); textSize = 14f
                setTextColor(if (dark) Color.parseColor("#EEEEEE") else Color.parseColor("#333333"))
                textDirection = android.view.View.TEXT_DIRECTION_LOCALE
                gravity = Gravity.START
                setPadding(0, 0, 0, dp(6))
            })
        }
        // 2.95: no Back button on this page (user order); the
        // system back button/gesture closes it, like the
        // Settings page since 2.91.
        root.addView(panel)
        setContentView(scroll)
        try {
                    } catch (_: Exception) {}
    }

